#ifndef MEP_LUA_LSP_H
#define MEP_LUA_LSP_H

// The analysis half of mep's own Lua language server (the wire half is
// lua_lsp_server.cpp, the `mep-lua-lsp` binary; the `lua_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (lua_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct LuaLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class LuaLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const LuaLspDocument> LuaLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class LuaLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct LuaLspDiagnostic {
    LuaLspRange range;
    LuaLspSeverity severity = LuaLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<LuaLspDiagnostic> LuaLspDiagnostics(const LuaLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string LuaLspFormatDiagnostic(const std::string &path, const LuaLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool LuaLspDiagnosticFails(const LuaLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class LuaLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct LuaLspCompletionItem {
    std::string label;
    std::string insert_text;
    LuaLspKind kind = LuaLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<LuaLspCompletionItem> LuaLspCompletions(const LuaLspDocument &doc, int line, int col);

struct LuaLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    LuaLspRange range;
};

LuaLspHoverInfo LuaLspHover(const LuaLspDocument &doc, int line, int col);

struct LuaLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

LuaLspSignatureHelp LuaLspSignatureAt(const LuaLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct LuaLspLocation {
    LuaLspRange range;
};

std::vector<LuaLspLocation> LuaLspDefinition(const LuaLspDocument &doc, int line, int col);

struct LuaLspReference {
    LuaLspRange range;
    bool is_definition = false;
};

std::vector<LuaLspReference> LuaLspReferences(const LuaLspDocument &doc, int line, int col);

struct LuaLspTextEdit {
    LuaLspRange range;
    std::string new_text;
};

struct LuaLspRenameTarget {
    bool found = false;
    LuaLspRange range;
    std::string placeholder;
};

LuaLspRenameTarget LuaLspPrepareRename(const LuaLspDocument &doc, int line, int col);
std::vector<LuaLspTextEdit> LuaLspRename(const LuaLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class LuaLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct LuaLspSymbol {
    std::string name;
    std::string detail;
    LuaLspSymbolKind kind = LuaLspSymbolKind::Variable;
    LuaLspRange range;
    LuaLspRange sel_range;
    int parent = -1;
};

std::vector<LuaLspSymbol> LuaLspSymbols(const LuaLspDocument &doc);

struct LuaLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<LuaLspFold> LuaLspFolds(const LuaLspDocument &doc);

/** @brief What `luac -p` says about the text: "" when it compiles, else "CHUNK:LINE: message". */
std::string LuaLspLuacCheck(const std::string &text, const std::string &chunkname);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<LuaLspTextEdit> LuaLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_LUA_LSP_H
